/**
 * BlockNote editor — client-only (ProseMirror needs a real DOM; the route
 * mounts this behind ClientOnly + lazy so it never renders during SSR and
 * never ships in the worker's server bundle).
 *
 * UI package: @blocknote/shadcn (v0.52 targets Tailwind v4 natively; its
 * utility classes are generated by our build via @source in styles.css and
 * resolve against the shadcn theme variables already defined there).
 * Persistence: publishing exports blocks → markdown (lossy) → record
 * textContent; drafts store the block JSON itself (lossless) and load it
 * back via `initialBlocks`.
 */
import "@blocknote/shadcn/style.css";

import type { BlockNoteEditor, PartialBlock } from "@blocknote/core";
import { en } from "@blocknote/core/locales";
import { useCreateBlockNote } from "@blocknote/react";
import { BlockNoteView } from "@blocknote/shadcn";
import { useEffect, useRef, useState } from "react";

import {
  createInlineImageUploader,
  type InlineImageStore,
  type UploadStatus,
} from "~/lib/inline-images";

export type { BlockNoteEditor };

/**
 * BlockNote's own image controls, relabelled.
 *
 * "Rename image" edits the block's `name` prop — which is the `alt` attribute
 * it renders and the `![alt](…)` text it exports on publish. Leaving it called
 * "rename" hides the only accessibility control the editor has behind a word
 * about filenames. Spread from the shipped English dictionary so a BlockNote
 * upgrade that adds strings doesn't lose them.
 */
const DICTIONARY = {
  ...en,
  formatting_toolbar: {
    ...en.formatting_toolbar,
    file_rename: {
      tooltip: {
        ...en.formatting_toolbar.file_rename.tooltip,
        image: "Edit alt text",
      },
      input_placeholder: {
        ...en.formatting_toolbar.file_rename.input_placeholder,
        image: "Describe this image for screen readers",
      },
    },
  },
};

export default function Editor({
  initialMarkdown,
  initialBlocks,
  imageStore,
  onChange,
  onReady,
}: {
  /** Markdown to load into the editor (edit flow); parsed via BlockNote's built-in parser. */
  initialMarkdown?: string;
  /** Draft blocks to load (resume flow); wins over initialMarkdown. */
  initialBlocks?: unknown[];
  /** Where uploaded body images are kept until the publish form submits them
   * (see ~/lib/inline-images). Absent = images can't be uploaded. */
  imageStore?: InlineImageStore;
  /** Fires on every document change (user edits AND programmatic loads). */
  onChange?: () => void;
  onReady: (editor: BlockNoteEditor) => void;
}) {
  // Announced politely and shown in print: an upload that fails has to say so
  // where the writer is looking, not only in BlockNote's own error state.
  const [status, setStatus] = useState<UploadStatus | null>(null);
  // useCreateBlockNote builds the editor once; reading the store through a
  // ref keeps the upload callback stable, because recreating the editor to
  // pick up a new prop identity would drop the writer's document.
  const storeRef = useRef(imageStore);
  useEffect(() => {
    storeRef.current = imageStore;
  }, [imageStore]);

  const editor = useCreateBlockNote({
    dictionary: DICTIONARY,
    uploadFile: createInlineImageUploader({
      store: () => storeRef.current,
      onStatus: setStatus,
    }),
    /** Uploaded-this-session images display from local bytes; everything else
     * (a published post's images, an external URL) resolves as written. */
    resolveFileUrl: async (url: string) =>
      storeRef.current?.display(url) ?? url,
  });

  // Initial content is applied exactly once per editor instance — a re-run
  // of the effect (e.g. a parent re-render changing a callback identity)
  // must never clobber what the writer has typed since.
  const appliedRef = useRef(false);

  useEffect(() => {
    if (!appliedRef.current) {
      appliedRef.current = true;
      let loaded = false;
      if (initialBlocks && initialBlocks.length > 0) {
        // Draft rows are written by our own editor, but guard the cast: a
        // malformed row must not crash the resume.
        try {
          editor.replaceBlocks(
            editor.document,
            initialBlocks as PartialBlock[],
          );
          loaded = true;
        } catch {
          // Fall through to the markdown projection. Opening EMPTY over a
          // draft that still has words is not a recovery — the next autosave
          // would write the blank document back over them.
        }
      }
      if (!loaded && initialMarkdown) {
        const blocks = editor.tryParseMarkdownToBlocks(initialMarkdown);
        if (blocks.length > 0) editor.replaceBlocks(editor.document, blocks);
      }
    }
    onReady(editor);
  }, [editor, initialMarkdown, initialBlocks, onReady]);

  // BlockNote paints its own surface and needs to be told which edition it is
  // in. This was pinned to "light", which is why the editor stayed a white box
  // on a dark page no matter how many tokens were overridden around it — the
  // component was never reading them.
  return (
    <>
      <BlockNoteView editor={editor} onChange={onChange} theme={useEdition()} />
      <p
        aria-live="polite"
        className={`mt-3 min-h-4 font-display text-xs leading-4 ${
          status?.tone === "error" ? "text-spot" : "text-ink-soft"
        }`}
        role="status"
      >
        {status?.message ?? ""}
      </p>
    </>
  );
}

/**
 * The edition currently in force, mirroring the pre-paint bootstrap in
 * `__root`. Subscribes to the attribute so a writer switching Appearance in
 * another tab — or the system flipping at dusk while on "System" — repaints the
 * editor rather than stranding it in the wrong one.
 */
function useEdition(): "light" | "dark" {
  const [edition, setEdition] = useState<"light" | "dark">(() =>
    typeof document === "undefined"
      ? "light"
      : document.documentElement.dataset.theme === "dark"
        ? "dark"
        : "light",
  );
  useEffect(() => {
    const read = () =>
      setEdition(
        document.documentElement.dataset.theme === "dark" ? "dark" : "light",
      );
    read();
    const observer = new MutationObserver(read);
    observer.observe(document.documentElement, {
      attributeFilter: ["data-theme"],
    });
    return () => observer.disconnect();
  }, []);
  return edition;
}
